const raw = $json.choices?.[0]?.message?.content || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    trust_score: 0,
    summary: 'The AI response could not be parsed.',
    verdict: 'Verification failed. Review the workflow output in n8n.',
    metrics: {
      factual_accuracy: 0,
      source_quality: 0,
      bias_detection: 0,
      logical_consistency: 0,
      completeness: 0
    },
    source_label: 'Invalid AI response'
  };
}

const clamp = (value) => Math.max(0, Math.min(100, Number.parseInt(value ?? 0, 10) || 0));
const metrics = parsed.metrics || {};

return [{
  json: {
    trust_score: clamp(parsed.trust_score),
    summary: String(parsed.summary || 'Verification completed.'),
    verdict: String(parsed.verdict || 'Verification completed.'),
    metrics: {
      factual_accuracy: clamp(metrics.factual_accuracy),
      source_quality: clamp(metrics.source_quality),
      bias_detection: clamp(metrics.bias_detection),
      logical_consistency: clamp(metrics.logical_consistency),
      completeness: clamp(metrics.completeness)
    },
    source_label: String(parsed.source_label || '')
  }
}];
